import{_ as t,b as e,a,aS as o}from"./chunks/framework.M2Whok06.js";const s="/assets/baidu_tj.CfRNT6fk.png",r="/assets/google_ad.ISKIpw9T.png",g=JSON.parse('{"title":"个人网站的广告收益","description":"","frontmatter":{},"headers":[],"relativePath":"note/stationmaster/seo/04-个人网站的广告收益.md","filePath":"note/stationmaster/seo/04-个人网站的广告收益.md","lastUpdated":1731776553000}'),p={name:"note/stationmaster/seo/04-个人网站的广告收益.md"},l=o('<h1 id="个人网站的广告收益" tabindex="-1">个人网站的广告收益 <a class="header-anchor" href="#个人网站的广告收益" aria-label="Permalink to &quot;个人网站的广告收益&quot;">​</a></h1><p>本篇主要分享下博主这个站点接入广告之后的收益情况。</p><p>个人网站真的非常非常难做，根本就没流量，如果你是想靠网站挂广告挣钱的话，恐怕要饿死。</p><p>如果你是个人IP的话，感觉应该可以，每日有个十几万的PV，比如阮一峰，廖雪峰这些大神的博客估计流量会很大</p><p>就拿我这个站点来说，接入的是谷歌广告，一天就几分钱，一天最多没超过3毛，当然是$哈， 我是有两个站点，都开了广告，一共加起来的话每日的PV有个300~500左右，UV的话大概就是80~120左右。 没有推广，就发了下csdn或者公众号之类的。没图说JB，看图 <img src="'+s+'" alt=""></p><p>下面是今天谷歌广告的收益，开通广告半月了，才挣了10块钱。</p><div class="tip custom-block github-alert"><p class="custom-block-title">谷歌广告体现要满100才可以，这要等到猴年马月才能提现勒</p><p></p></div><p><img src="'+r+'" alt=""></p><p>谷歌广告是靠点击收费的，展现还不算。还是挺难的。</p><ul><li>为什么接入谷歌广告不接入百度广告呢？</li></ul><p>百度没给我审核通过，又慢又事逼，谷歌1周时间就给我通过了。就连现在百度还没把我的网站收录，我每天都手动提交链接 外加用api调用提交。坚持1个月了，还没有给我收录。</p><ul><li>谷歌广告的费用高么？</li></ul><p>我感觉应该和微信小程序的广告单价差不多。点击一下估计会有个几分几毛钱。</p><ul><li>网站接入广告影响用户浏览，为啥不去掉？</li></ul><p>蚊子再小也是肉啊，而且我觉得，假如你的文章真的给用户带来了价值，用户是可以接受广告的。可能有的用户还会主动帮你点击下， 就比如我就是这样的人，看到一篇文章解决了我的问题，没账号也要专门注册一个评论一下作者以表达感激之情。so？屏幕前的你， 确定不帮我click下广告么😁</p><blockquote><p>我也是第一次接入网站广告，还在不断地摸索中，本文章持续更新。</p></blockquote><h2 id="谷歌广告pin码一直收不到怎么办" tabindex="-1">谷歌广告PIN码一直收不到怎么办？ <a class="header-anchor" href="#谷歌广告pin码一直收不到怎么办" aria-label="Permalink to &quot;谷歌广告PIN码一直收不到怎么办？&quot;">​</a></h2><blockquote><p><a href="https://www.blogbig.cn/archives/GoogleAdsensePIN.html" target="_blank" rel="noreferrer">https://www.blogbig.cn/archives/GoogleAdsensePIN.html</a> <br><a href="https://blog.csdn.net/qq_43079386/article/details/137061313" target="_blank" rel="noreferrer">https://blog.csdn.net/qq_43079386/article/details/137061313</a></p></blockquote><p>1.找了谷歌官方社区的人咨询</p><p>最后给了一个这个链接</p><p><a href="https://support.google.com/adsense/contact/id_verification" target="_blank" rel="noreferrer">https://support.google.com/adsense/contact/id_verification</a></p><p>填了表格以后,很快收到了邮箱的提醒,配置下付款方式就完成了~</p><h2 id="广告账户限制问题" tabindex="-1">广告账户限制问题 <a class="header-anchor" href="#广告账户限制问题" aria-label="Permalink to &quot;广告账户限制问题&quot;">​</a></h2><p><a href="https://support.google.com/admob/thread/160170758/%E6%88%91%E7%9A%84%E5%B9%BF%E5%91%8A%E8%B4%A6%E6%88%B7%E9%99%90%E5%88%B6%E5%B7%B2%E7%BB%8F%E8%B6%85%E8%BF%8760%E5%A4%A9%E4%BA%86%E6%88%91%E8%AF%A5%E6%80%8E%E4%B9%88%E5%8A%9E?hl=zh-Hans" target="_blank" rel="noreferrer">https://support.google.com/admob/thread/160170758/我的广告账户限制已经超过60天了我该怎么办?hl=zh-Hans</a></p>',24),i=[l];function n(c,_,h,d,m,u){return a(),e("div",null,i)}const f=t(p,[["render",n]]);export{g as __pageData,f as default};
